// 需求确认放行。第 1 步：统计体积 + 检查 .gitignore 现状
const r = await tools.pwsh({
  command: `
Write-Host '=== 各数据源体积 ==='
foreach ($d in @("$env:DSH_HOME\.dsh-memory", "$env:USERPROFILE\.openviking", "$env:DSH_HOME\grill-first", "$env:DSH_HOME\sessions", "$env:DSH_HOME\storages")) {
  if (Test-Path $d) {
    $m = Get-ChildItem $d -Recurse -File -ErrorAction SilentlyContinue | Measure-Object Length -Sum
    "{0,-50} {1,8:N2} MB  {2,5} 文件" -f (Split-Path $d -Leaf), ($m.Sum/1MB), $m.Count
  }
}
Write-Host '=== .gitignore 现状 ==='
Get-Content "D:\\GitHub\\My-second-brain\.gitignore" -Raw
Write-Host '=== 敏感文件探测（密钥/token） ==='
$hits = Get-ChildItem "$env:DSH_HOME\sessions","$env:DSH_HOME\storages","$env:USERPROFILE\.openviking","$env:DSH_HOME\.dsh-memory" -Recurse -File -ErrorAction SilentlyContinue | Where-Object { $_.Extension -in '.yaml','.yml','.env' -or $_.Name -match 'credential|secret|token|\.env' } | Select-Object FullName
if ($hits) { $hits | Out-String } else { "无按文件名/扩展名命中的敏感文件" }
`,
  description: "统计数据体积并探测敏感文件"
});
console.log(r.stdout);
